import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.global.ct.frameinventory.Application;
import com.sun.net.httpserver.HttpServer;
import io.sentry.Sentry;
import java.net.InetSocketAddress;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.LinkedBlockingQueue;
import java.util.concurrent.TimeUnit;
import java.util.zip.GZIPInputStream;
import org.springframework.boot.builder.SpringApplicationBuilder;
import org.springframework.boot.web.servlet.context.ServletWebServerApplicationContext;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

class SentrySmoke {
    public static void main(String[] args) throws Exception {
        boolean enabled = Boolean.parseBoolean(args[0]);
        var envelopes = new LinkedBlockingQueue<String>();
        var receiver = HttpServer.create(new InetSocketAddress("127.0.0.1", 18443), 0);
        receiver.createContext("/api/1/envelope/", exchange -> {
            try (var body = "gzip".equals(exchange.getRequestHeaders().getFirst("Content-Encoding"))
                    ? new GZIPInputStream(exchange.getRequestBody()) : exchange.getRequestBody()) {
                envelopes.add(new String(body.readAllBytes(), StandardCharsets.UTF_8));
                exchange.sendResponseHeaders(200, -1);
            } finally {
                exchange.close();
            }
        });
        receiver.start();
        try (var context = (ServletWebServerApplicationContext)
                new SpringApplicationBuilder(Application.class, FailureController.class)
                        .run("--server.port=0", "--spring.flyway.enabled=false")) {
            var baseUrl = "http://127.0.0.1:" + context.getWebServer().getPort();
            try (var client = HttpClient.newHttpClient()) {
                check(client.send(HttpRequest.newBuilder(URI.create(baseUrl + "/api/health")).build(),
                        HttpResponse.BodyHandlers.ofString()).statusCode() == 200, "health");
                check(client.send(HttpRequest.newBuilder(URI.create(baseUrl + "/sentry-smoke")).build(),
                        HttpResponse.BodyHandlers.ofString()).statusCode() == 500, "controlled exception");
            }
            Sentry.flush(5000);
            if (enabled) {
                var envelope = envelopes.poll(10, TimeUnit.SECONDS);
                check(envelope != null, "event arrived");
                var lines = envelope.split("\n");
                var mapper = new ObjectMapper();
                check(mapper.readTree(lines[1]).path("type").asText().equals("event"), "event type");
                var event = mapper.readTree(lines[2]);
                check(event.path("environment").asText().equals("smoke"), "environment tag");
                boolean exceptionCaptured = false;
                for (JsonNode exception : event.path("exception").path("values")) {
                    if (exception.path("value").asText().equals("GLO-7 Sentry smoke exception")) {
                        check(!exception.path("stacktrace").path("frames").isEmpty(), "stack trace");
                        exceptionCaptured = true;
                    }
                }
                check(exceptionCaptured, "controlled exception payload");
            } else {
                check(!Sentry.isEnabled(), "Sentry disabled");
                check(envelopes.poll(1, TimeUnit.SECONDS) == null, "no event sent");
            }
            System.out.println("Sentry smoke check passed, enabled=" + enabled);
        } finally {
            receiver.stop(0);
        }
    }

    private static void check(boolean condition, String description) {
        if (!condition) {
            throw new AssertionError(description);
        }
    }

    @RestController
    public static class FailureController {
        @GetMapping("/sentry-smoke")
        public void fail() {
            throw new IllegalStateException("GLO-7 Sentry smoke exception");
        }
    }
}

